<?php
declare(strict_types=1);

function recharge_expenses_schema(mysqli $db): void {
  if(!$db->query("CREATE TABLE IF NOT EXISTS erp_employee_recharge_expenses (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    employee_username VARCHAR(100) NOT NULL,
    employee_name VARCHAR(160) NOT NULL,
    employee_level CHAR(1) NOT NULL,
    mobile_number VARCHAR(15) NOT NULL,
    operator_name VARCHAR(40) NOT NULL,
    recharge_date DATE NOT NULL,
    plan_name VARCHAR(120) NOT NULL,
    validity_days INT UNSIGNED NOT NULL DEFAULT 84,
    amount DECIMAL(10,2) NOT NULL,
    reference_number VARCHAR(120) NOT NULL DEFAULT '',
    notes VARCHAR(1000) NOT NULL DEFAULT '',
    receipt_path VARCHAR(255) NULL,
    receipt_name VARCHAR(180) NULL,
    receipt_mime VARCHAR(80) NULL,
    status ENUM('SUBMITTED','APPROVED','REJECTED','SETTLED') NOT NULL DEFAULT 'SUBMITTED',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_recharge_employee_date (employee_username,recharge_date),
    KEY idx_recharge_status_date (status,recharge_date)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"))throw new RuntimeException('Recharge expense storage is unavailable.');
  $columns=['special_approved_amount'=>"DECIMAL(10,2) NOT NULL DEFAULT 0",'approved_amount'=>"DECIMAL(10,2) NOT NULL DEFAULT 0",'hr_approval_note'=>"VARCHAR(500) NOT NULL DEFAULT ''",'reviewed_by'=>"VARCHAR(100) NULL",'reviewed_at'=>"DATETIME NULL",'settled_by'=>"VARCHAR(100) NULL",'settled_at'=>"DATETIME NULL"];$result=$db->query('SHOW COLUMNS FROM erp_employee_recharge_expenses');$existing=[];if($result){while($row=$result->fetch_assoc())$existing[(string)$row['Field']]=true;}foreach($columns as $name=>$definition)if(!isset($existing[$name]))$db->query("ALTER TABLE erp_employee_recharge_expenses ADD COLUMN `{$name}` {$definition}");
}

function recharge_expenses_text($value,int $max): string {$text=trim((string)($value??''));return function_exists('mb_substr')?mb_substr($text,0,$max,'UTF-8'):substr($text,0,$max);}
function recharge_expenses_policy(array $actor): array {
  $level=strtoupper(trim((string)($actor['employeeLevel']??'')));$level=preg_replace('/^LEVEL\s+/','',$level)??'';
  if($level==='A')return ['level'=>'A','plan'=>'2 GB/day · 84 days','amount'=>859.0,'validity'=>84];
  if($level==='B')return ['level'=>'B','plan'=>'1.5 GB/day · 84 days','amount'=>799.0,'validity'=>84];
  return ['level'=>$level,'plan'=>'Not applicable','amount'=>0.0,'validity'=>0];
}
function recharge_expenses_attachment(array $file,string $username): ?array {
  $error=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($error===UPLOAD_ERR_NO_FILE)return null;$tmp=(string)($file['tmp_name']??'');$size=(int)($file['size']??0);
  if($error!==UPLOAD_ERR_OK||$size<=0||$size>5*1024*1024||!is_uploaded_file($tmp))respond(['status'=>'error','message'=>'Receipt upload failed or exceeds 5 MB.'],400);
  $mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'';$extensions=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($extensions[$mime]))respond(['status'=>'error','message'=>'Attach a JPG, PNG, or PDF recharge receipt.'],415);
  $segment=preg_replace('/[^A-Za-z0-9._-]+/','-',trim($username))?:'employee';$relative='recharge_expense/'.trim($segment,'.-_');$folder=erp_persistent_storage_path($relative);if(!is_dir($folder)&&!mkdir($folder,0750,true)&&!is_dir($folder))throw new RuntimeException('Recharge receipt folder could not be created.');
  $name=bin2hex(random_bytes(18)).'.'.$extensions[$mime];if(!move_uploaded_file($tmp,$folder.DIRECTORY_SEPARATOR.$name))throw new RuntimeException('Recharge receipt could not be saved.');
  return ['path'=>$relative.'/'.$name,'name'=>recharge_expenses_text($file['name']??'receipt',180),'mime'=>$mime];
}

function recharge_expenses_handle(mysqli $db,array $actor,string $action,string $method): void {
  recharge_expenses_schema($db);$username=recharge_expenses_text($actor['username']??'',100);$employeeName=recharge_expenses_text($actor['name']??$username,160);
  if($action==='recharge_receipt'&&$method==='GET'){
    $id=(int)($_GET['id']??0);$stmt=$db->prepare('SELECT employee_username,receipt_path,receipt_name,receipt_mime FROM erp_employee_recharge_expenses WHERE id=? LIMIT 1');$stmt->bind_param('i',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();
    if(!$row||empty($row['receipt_path']))respond(['status'=>'error','message'=>'Recharge receipt not found.'],404);if(!hash_equals((string)$row['employee_username'],$username)&&!admin($actor)&&!tour_expenses_is_hr($actor)&&!tour_expenses_actor_can_reimburse($actor))respond(['status'=>'error','message'=>'You cannot view this recharge receipt.'],403);
    $file=erp_existing_storage_path((string)$row['receipt_path']);if(!erp_path_is_inside($file,erp_persistent_storage_path('recharge_expense'))||!is_file($file))respond(['status'=>'error','message'=>'Recharge receipt file not found.'],404);
    $safe=str_replace('"','',preg_replace('/[^A-Za-z0-9._ -]/','_',basename((string)$row['receipt_name']))?:'receipt');header_remove('Content-Type');header('Content-Type: '.((string)$row['receipt_mime']?:'application/octet-stream'));header('Content-Length: '.(string)filesize($file));header('Content-Disposition: inline; filename="'.$safe.'"');header('Cache-Control: no-store, private');readfile($file);exit;
  }
