  if($method==='GET'){
    $scope=strtolower((string)($_GET['scope']??'mine'));$where='employee_username=?';$bind=$username;if($scope==='pending'){if(!tour_expenses_actor_can_approve($db,$actor))respond(['status'=>'error','message'=>'Only the Human Resources Manager can review recharge claims.'],403);$where="status='SUBMITTED'";$bind=null;}elseif($scope==='reimburse'){if(!tour_expenses_actor_can_reimburse($actor))respond(['status'=>'error','message'=>'Only Accounts can view approved recharge claims.'],403);$where="status IN ('APPROVED','SETTLED')";$bind=null;}
    $stmt=$db->prepare("SELECT id,employee_username,employee_name,employee_level,mobile_number,operator_name,recharge_date,plan_name,validity_days,amount,reference_number,notes,receipt_path,receipt_name,receipt_mime,status,special_approved_amount,approved_amount,hr_approval_note,reviewed_by,reviewed_at,settled_by,settled_at,created_at FROM erp_employee_recharge_expenses WHERE {$where} ORDER BY recharge_date DESC,id DESC");if($bind!==null)$stmt->bind_param('s',$bind);$stmt->execute();$result=$stmt->get_result();$claims=[];while($row=$result->fetch_assoc()){$id=(int)$row['id'];$claims[]=['id'=>$id,'employeeUsername'=>$row['employee_username'],'employeeName'=>$row['employee_name'],'level'=>$row['employee_level'],'mobileNumber'=>$row['mobile_number'],'operator'=>$row['operator_name'],'date'=>$row['recharge_date'],'plan'=>$row['plan_name'],'validityDays'=>(int)$row['validity_days'],'amount'=>(float)$row['amount'],'reference'=>$row['reference_number'],'notes'=>$row['notes'],'receiptName'=>$row['receipt_name'],'receiptUrl'=>empty($row['receipt_path'])?'':'backend/api.php?action=recharge_receipt&id='.$id,'status'=>$row['status'],'specialApprovedAmount'=>(float)$row['special_approved_amount'],'approvedAmount'=>(float)$row['approved_amount'],'hrApprovalNote'=>$row['hr_approval_note'],'reviewedBy'=>$row['reviewed_by'],'reviewedAt'=>$row['reviewed_at'],'settledBy'=>$row['settled_by'],'settledAt'=>$row['settled_at'],'createdAt'=>$row['created_at']];}$stmt->close();respond(['status'=>'success','scope'=>$scope,'policy'=>recharge_expenses_policy($actor),'claims'=>$claims]);
  }
  if($method!=='POST')respond(['status'=>'error','message'=>'Unsupported recharge request.'],405);$isJson=str_starts_with(strtolower((string)($_SERVER['CONTENT_TYPE']??'')),'application/json');$input=$isJson?json_body():$_POST;$operation=(string)($input['operation']??'create');
  if($operation==='save_special'){
    if(!tour_expenses_actor_can_approve($db,$actor))respond(['status'=>'error','message'=>'Only the Human Resources Manager can approve excess recharge claims.'],403);$id=(int)($input['id']??0);$special=max(0.0,(float)($input['specialAmount']??0));$note=recharge_expenses_text($input['hrNote']??'',500);$check=$db->prepare("SELECT amount,employee_level,status FROM erp_employee_recharge_expenses WHERE id=? LIMIT 1");$check->bind_param('i',$id);$check->execute();$row=$check->get_result()->fetch_assoc();$check->close();if(!$row||$row['status']!=='SUBMITTED')respond(['status'=>'error','message'=>'Recharge claim is not awaiting approval.'],409);$p=tour_expenses_policy((string)$row['employee_level']);$allowed=min((float)$row['amount'],(float)($p['mobileMax']??0));$difference=max(0.0,(float)$row['amount']-$allowed);if($special>$difference)respond(['status'=>'error','message'=>'Special approval cannot exceed ₹'.number_format($difference,2).'.'],400);if($special>0&&$note==='')respond(['status'=>'error','message'=>'Add an HR note for special approval.'],400);$approved=$allowed+$special;$save=$db->prepare('UPDATE erp_employee_recharge_expenses SET special_approved_amount=?,approved_amount=?,hr_approval_note=? WHERE id=?');$save->bind_param('ddsi',$special,$approved,$note,$id);$save->execute();$save->close();respond(['status'=>'success','message'=>'Recharge approval values saved.']);
  }
  if($operation==='review'){
    if(!tour_expenses_actor_can_approve($db,$actor))respond(['status'=>'error','message'=>'Only the Human Resources Manager can review recharge claims.'],403);$id=(int)($input['id']??0);$decision=strtoupper((string)($input['decision']??''));if(!in_array($decision,['APPROVED','REJECTED'],true))respond(['status'=>'error','message'=>'Choose approve or reject.'],400);$owner=$db->query('SELECT employee_username FROM erp_employee_recharge_expenses WHERE id='.$id)->fetch_assoc();$reviewer=recharge_expenses_text($actor['name']??$username,100);if($decision==='APPROVED')$db->query("UPDATE erp_employee_recharge_expenses SET approved_amount=LEAST(amount,CASE employee_level WHEN 'A' THEN 859 WHEN 'B' THEN 799 ELSE 0 END)+LEAST(special_approved_amount,GREATEST(0,amount-LEAST(amount,CASE employee_level WHEN 'A' THEN 859 WHEN 'B' THEN 799 ELSE 0 END))) WHERE id=".$id);$stmt=$db->prepare("UPDATE erp_employee_recharge_expenses SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='SUBMITTED'");$stmt->bind_param('ssi',$decision,$reviewer,$id);$stmt->execute();$changed=$stmt->affected_rows;$stmt->close();if(!$changed)respond(['status'=>'error','message'=>'Recharge claim was already processed.'],409);try{$audit=append_audit_event($db,$actor,'HR','RECHARGE_EXPENSE_'.$decision,ucfirst(strtolower($decision)).' recharge claim #'.$id.'.');[$auditId,$auditLegacy]=erp_notification_audit_link($db,$audit);erp_notification_resolve_group($db,'RECHARGE_EXPENSE:'.$id.':HR',$reviewer,$auditId,$auditLegacy);if(!empty($owner['employee_username']))erp_notification_send_to_username($db,(string)$owner['employee_username'],['type'=>$decision==='APPROVED'?'SUCCESS':'WARNING','category'=>'APPROVAL','title'=>'Recharge claim '.strtolower($decision),'message'=>$reviewer.' '.strtolower($decision).' recharge claim #'.$id.'.','entityType'=>'RECHARGE_EXPENSE','entityId'=>(string)$id,'targetView'=>'expensesRecharge','auditEventId'=>$auditId,'auditLegacyId'=>$auditLegacy]);}catch(Throwable $notifyError){error_log('Recharge review notification failed: '.$notifyError->getMessage());}respond(['status'=>'success','message'=>'Recharge claim '.strtolower($decision).'.']);
  }
  if($operation==='settle'){
    if(!tour_expenses_actor_can_reimburse($actor))respond(['status'=>'error','message'=>'Only Accounts can settle recharge claims.'],403);$id=(int)($input['id']??0);$ownerStmt=$db->prepare("SELECT employee_username FROM erp_employee_recharge_expenses WHERE id=? AND status='APPROVED' LIMIT 1");$ownerStmt->bind_param('i',$id);$ownerStmt->execute();$owner=$ownerStmt->get_result()->fetch_assoc();$ownerStmt->close();if(!$owner)respond(['status'=>'error','message'=>'Recharge claim is not awaiting settlement.'],409);$settledBy=recharge_expenses_text($actor['name']??$username,100);$stmt=$db->prepare("UPDATE erp_employee_recharge_expenses SET status='SETTLED',settled_by=?,settled_at=NOW() WHERE id=? AND status='APPROVED'");$stmt->bind_param('si',$settledBy,$id);$stmt->execute();$changed=$stmt->affected_rows;$stmt->close();if(!$changed)respond(['status'=>'error','message'=>'Recharge claim is not awaiting settlement.'],409);
    try{$audit=append_audit_event($db,$actor,'ACCOUNTS','RECHARGE_REIMBURSEMENT_SETTLED','Settled HR-approved recharge reimbursement #'.$id.' for '.(string)$owner['employee_username'].'.');[$auditId,$auditLegacy]=erp_notification_audit_link($db,$audit);erp_notification_send_to_username($db,(string)$owner['employee_username'],['type'=>'SUCCESS','category'=>'APPROVAL','priority'=>'NORMAL','title'=>'Recharge reimbursement settled','message'=>$settledBy.' marked recharge claim #'.$id.' as settled by Accounts.','entityType'=>'RECHARGE_EXPENSE','entityId'=>(string)$id,'targetView'=>'expensesRecharge','auditEventId'=>$auditId,'auditLegacyId'=>$auditLegacy]);}catch(Throwable $notifyError){error_log('Recharge settlement notification failed: '.$notifyError->getMessage());}
    respond(['status'=>'success','message'=>'Recharge reimbursement settled.']);
  }
  $policy=recharge_expenses_policy($actor);if(($policy['amount']??0)<=0)respond(['status'=>'error','message'=>'Mobile recharge reimbursement is not applicable for your employee level.'],400);
  $mobile=preg_replace('/\D+/','',(string)($_POST['mobileNumber']??''))??'';$operator=recharge_expenses_text($_POST['operator']??'',40);$date=recharge_expenses_text($_POST['rechargeDate']??'',10);$plan=recharge_expenses_text($_POST['plan']??'',120);$amount=(float)($_POST['amount']??0);$reference=recharge_expenses_text($_POST['reference']??'',120);$notes=recharge_expenses_text($_POST['notes']??'',1000);$parsed=DateTime::createFromFormat('!Y-m-d',$date);
  if(strlen($mobile)<10||strlen($mobile)>15||$operator===''||!$parsed||$parsed->format('Y-m-d')!==$date||$plan===''||$amount<=0)respond(['status'=>'error','message'=>'Enter a valid mobile number, operator, recharge date, plan, and amount.'],400);
  $receipt=isset($_FILES['receipt'])?recharge_expenses_attachment($_FILES['receipt'],$username):null;$path=$receipt['path']??null;$receiptName=$receipt['name']??null;$mime=$receipt['mime']??null;$level=(string)$policy['level'];$validity=(int)$policy['validity'];
  $stmt=$db->prepare("INSERT INTO erp_employee_recharge_expenses(employee_username,employee_name,employee_level,mobile_number,operator_name,recharge_date,plan_name,validity_days,amount,reference_number,notes,receipt_path,receipt_name,receipt_mime,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'SUBMITTED')");if(!$stmt)throw new RuntimeException('Recharge claim could not be prepared.');$stmt->bind_param('sssssssidsssss',$username,$employeeName,$level,$mobile,$operator,$date,$plan,$validity,$amount,$reference,$notes,$path,$receiptName,$mime);if(!$stmt->execute()){if($receipt)@unlink(erp_existing_storage_path((string)$receipt['path']));throw new RuntimeException('Recharge claim could not be saved.');}$id=(int)$stmt->insert_id;$stmt->close();
  try{$audit=append_audit_event($db,$actor,'HR','RECHARGE_EXPENSE_SUBMITTED','Submitted mobile recharge claim #'.$id.' under Level '.$level.'.');[$auditId,$auditLegacy]=erp_notification_audit_link($db,$audit);$notice=['type'=>'APPROVAL','category'=>'APPROVAL','priority'=>'HIGH','title'=>'Recharge claim needs approval','message'=>$employeeName.' submitted recharge claim #'.$id.' for ₹'.number_format($amount,2).'.','entityType'=>'RECHARGE_EXPENSE','entityId'=>(string)$id,'targetView'=>'hrTourExpenses','targetPayload'=>['scope'=>'pending'],'approvalGroupKey'=>'RECHARGE_EXPENSE:'.$id.':HR','actionable'=>true,'auditEventId'=>$auditId,'auditLegacyId'=>$auditLegacy];foreach(tour_expenses_hr_managers($db) as $manager)erp_notification_create($db,$manager,$notice);}catch(Throwable $error){error_log('Recharge audit/notification failed: '.$error->getMessage());}
  respond(['status'=>'success','message'=>'Recharge claim submitted successfully.','id'=>$id]);
